import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K,
    .param .u32 K_chunk
)
{
    .reg .u32 %r<120>;
    .reg .u64 %rd<70>;
    .reg .f32 %f<40>;
    .reg .pred %p<20>;
    .shared .align 16 .f32 smA[1024];
    .shared .align 16 .f32 smB[1024];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];
    ld.param.u32 %r4, [K_chunk];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    // thread indices
    mov.u32 %r5, %tid.y;
    mov.u32 %r6, %tid.x;
    mov.u32 %r7, %ctaid.y;
    mov.u32 %r8, %ctaid.x;
    mov.u32 %r9, %ctaid.z;
    // row, col
    mov.u32 %r10, %ntid.y;
    mad.lo.u32 %r11, %r7, %r10, %r5;
    mov.u32 %r12, %ntid.x;
    mad.lo.u32 %r13, %r8, %r12, %r6;
    // split-K range
    mul.lo.u32 %r14, %r9, %r4;
    add.u32 %r15, %r14, %r4;
    setp.gt.u32 %p1, %r15, %r3;
    selp.b32 %r16, %r3, %r15, %p1;
    // validity predicates (row/col within output bounds)
    setp.lt.u32 %p2, %r11, %r1;
    setp.lt.u32 %p3, %r13, %r2;
    // ---- precompute shared-memory store addresses (K_TILE = 64) ----
    // A: tile is [16 rows][64 cols]; each thread stores a 4-wide vector at cols [tx*4, tx*4+4)
    mul.lo.u32 %r40, %r6, 4;
    mad.lo.u32 %r17, %r5, 64, %r40;
    shl.b32 %r18, %r17, 2;
    mov.u32 %r19, smA;
    add.u32 %r20, %r19, %r18;
    // B: tile is [64 rows][16 cols]; thread (ty,tx) owns rows ty, ty+16, ty+32, ty+48
    mad.lo.u32 %r50, %r5, 16, %r6;
    shl.b32 %r51, %r50, 2;
    mov.u32 %r21, smB;
    add.u32 %r22, %r21, %r51;
    add.u32 %r52, %r22, 1024;
    add.u32 %r53, %r22, 2048;
    add.u32 %r54, %r22, 3072;
    // A row base pointer = A_ptr + row*K*4
    cvt.u64.u32 %rd4, %r11;
    cvt.u64.u32 %rd5, %r3;
    mul.lo.u64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.u64 %rd8, %rd1, %rd7;
    // B col base pointer = B_ptr + col*4
    cvt.u64.u32 %rd9, %r13;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd2, %rd10;
    // N stride in bytes
    cvt.u64.u32 %rd12, %r2;
    shl.b64 %rd13, %rd12, 2;
    mov.f32 %f1, 0f00000000;
    mov.u32 %r23, %r14;
TILE_LOOP:
    setp.ge.u32 %p4, %r23, %r16;
    @%p4 bra TILE_LOOP_END;
    // ---- vectorized load of A tile row (4 contiguous floats) ----
    add.u32 %r41, %r23, %r40;
    cvt.u64.u32 %rd30, %r41;
    shl.b64 %rd31, %rd30, 2;
    add.u64 %rd32, %rd8, %rd31;
    @%p2 ld.global.v4.f32 {%f10, %f11, %f12, %f13}, [%rd32];
    @!%p2 mov.f32 %f10, 0f00000000;
    @!%p2 mov.f32 %f11, 0f00000000;
    @!%p2 mov.f32 %f12, 0f00000000;
    @!%p2 mov.f32 %f13, 0f00000000;
    st.shared.v4.f32 [%r20], {%f10, %f11, %f12, %f13};
    // ---- load B tile rows ty, ty+16, ty+32, ty+48 (scalar, coalesced across tx) ----
    add.u32 %r60, %r23, %r5;
    cvt.u64.u32 %rd33, %r60;
    mul.lo.u64 %rd34, %rd33, %rd13;
    add.u64 %rd35, %rd11, %rd34;
    @%p3 ld.global.f32 %f14, [%rd35];
    @!%p3 mov.f32 %f14, 0f00000000;
    st.shared.f32 [%r22], %f14;
    add.u32 %r61, %r60, 16;
    cvt.u64.u32 %rd36, %r61;
    mul.lo.u64 %rd37, %rd36, %rd13;
    add.u64 %rd38, %rd11, %rd37;
    @%p3 ld.global.f32 %f15, [%rd38];
    @!%p3 mov.f32 %f15, 0f00000000;
    st.shared.f32 [%r52], %f15;
    add.u32 %r62, %r60, 32;
    cvt.u64.u32 %rd39, %r62;
    mul.lo.u64 %rd41, %rd39, %rd13;
    add.u64 %rd42, %rd11, %rd41;
    @%p3 ld.global.f32 %f16, [%rd42];
    @!%p3 mov.f32 %f16, 0f00000000;
    st.shared.f32 [%r53], %f16;
    add.u32 %r63, %r60, 48;
    cvt.u64.u32 %rd43, %r63;
    mul.lo.u64 %rd44, %rd43, %rd13;
    add.u64 %rd45, %rd11, %rd44;
    @%p3 ld.global.f32 %f17, [%rd45];
    @!%p3 mov.f32 %f17, 0f00000000;
    st.shared.f32 [%r54], %f17;
    bar.sync 0;
    mov.u32 %r26, 0;
INNER_LOOP:
    setp.ge.u32 %p9, %r26, 64;
    @%p9 bra INNER_LOOP_END;
    mad.lo.u32 %r27, %r5, 64, %r26;
    shl.b32 %r28, %r27, 2;
    add.u32 %r30, %r19, %r28;
    ld.shared.f32 %f4, [%r30];
    mad.lo.u32 %r31, %r26, 16, %r6;
    shl.b32 %r32, %r31, 2;
    add.u32 %r34, %r21, %r32;
    ld.shared.f32 %f5, [%r34];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    add.u32 %r26, %r26, 1;
    bra INNER_LOOP;
INNER_LOOP_END:
    bar.sync 0;
    add.u32 %r23, %r23, 64;
    bra TILE_LOOP;
TILE_LOOP_END:
    and.pred %p10, %p2, %p3;
    @!%p10 bra DONE;
    cvt.u64.u32 %rd20, %r11;
    cvt.u64.u32 %rd21, %r2;
    mul.lo.u64 %rd22, %rd20, %rd21;
    cvt.u64.u32 %rd23, %r13;
    add.u64 %rd24, %rd22, %rd23;
    shl.b64 %rd25, %rd24, 2;
    add.u64 %rd26, %rd3, %rd25;
    atom.global.add.f32 %f6, [%rd26], %f1;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions of A and B must match"
        C = torch.zeros((M, N), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        SPLIT_K = 64
        K_chunk = (K + SPLIT_K - 1) // SPLIT_K
        block = (16, 16, 1)
        grid = (
            (N + block[0] - 1) // block[0],
            (M + block[1] - 1) // block[1],
            SPLIT_K,
        )
        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(M), i32(N), i32(K), i32(K_chunk)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
